package net.atlasauth.pca;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import org.junit.jupiter.api.Test;

/**
 * 0.5 mutation kills for {@link Optimistic}: a differential test against the TS reference (the shared k05 oracle,
 * test-data/k05-optimistic.json.gz, generated by tools/pca-audit/k05-oracles/optimistic-oracle.mts), plus the inputs JSON cannot
 * carry (NaN / infinite numbers, a value the canonical form does not support).
 */
public class K05OptimisticDiffTest {
    static final String MODULE = "k05-optimistic";
    static final double NOW = 1_800_000_000_000d;

    @SuppressWarnings("unchecked") static Map<String, Object> m(Object o) { return (Map<String, Object>) o; }
    static double d(Object o) { return IntentJs.num(o); }

    interface Fn { Object apply(List<?> a) throws Exception; }

    static void each(String fn, Fn f) throws Exception {
        List<Map<String, Object>> cases = K05Oracle.of(MODULE, fn);
        assertFalse(cases.isEmpty(), "no oracle cases for " + fn);
        List<String> bad = new ArrayList<>();
        for (Map<String, Object> c : cases) {
            Object want = c.get("out"), got = null;
            Throwable err = null;
            try { got = f.apply((List<?>) c.get("args")); } catch (Throwable t) { err = t; }
            if (err != null) bad.add(c.get("name") + "\n  want: " + want + "\n  got:  THROWS " + err);
            else if (!IntentJs.jsonEquals(want, got)) bad.add(c.get("name") + "\n  want: " + want + "\n  got:  " + got);
        }
        assertTrue(bad.isEmpty(), bad.size() + " of " + cases.size() + " divergent case(s):\n" + String.join("\n", bad.subList(0, Math.min(bad.size(), 40))));
    }

    static Optimistic.ChallengeWindowPolicy policy(Object po) {
        Map<String, Object> p = m(po);
        return new Optimistic.ChallengeWindowPolicy(d(p.get("minWindowMs")), d(p.get("maxWindowMs")), d(p.get("maxSkewMs")));
    }

    static Object arg0(String fn, String name) throws Exception {
        for (Map<String, Object> c : K05Oracle.of(MODULE, fn)) if ((fn + "/" + name).equals(c.get("name"))) return ((List<?>) c.get("args")).get(0);
        throw new AssertionError("no oracle case " + fn + "/" + name);
    }

    @Test void claimCheck() throws Exception {
        each("claimCheck", a -> Optimistic.claimCheck(a.get(0), (String) a.get(1), (String) a.get(2), d(a.get(3)), policy(a.get(4))));
    }

    @Test void fraudProofWireCheck() throws Exception { each("fraudProofWireCheck", a -> Optimistic.fraudProofWireCheck(a.get(0), a.get(1))); }

    @Test void settlementWireCheck() throws Exception { each("settlementWireCheck", a -> Optimistic.settlementWireCheck(a.get(0), (String) a.get(1))); }

    @Test void claimNumbersJsonCannotCarry() throws Exception {
        Map<String, Object> base = m(arg0("claimCheck", "base"));
        String signer = Keys.edFromSeed(seed(91)).id();
        Optimistic.ChallengeWindowPolicy def = Optimistic.DEFAULT_POLICY;
        assertEquals("ok", Optimistic.claimCheck(base, "D", signer, NOW, def));
        for (double bad : new double[] {Double.NaN, Double.POSITIVE_INFINITY, Double.NEGATIVE_INFINITY}) {
            Map<String, Object> c = new LinkedHashMap<>(base);
            c.put("claimed_r", bad);
            assertEquals("claimed_r", Optimistic.claimCheck(c, "D", signer, NOW, def), "claimed_r " + bad);
            Map<String, Object> w = new LinkedHashMap<>(base);
            w.put("challenge_window_ms", bad);
            assertEquals("window", Optimistic.claimCheck(w, "D", signer, NOW, def), "window " + bad);
        }
        // a server time that is not finite is never in the window, even under a policy without a skew bound
        Optimistic.ChallengeWindowPolicy unbounded = new Optimistic.ChallengeWindowPolicy(1000, 86_400_000, Double.POSITIVE_INFINITY);
        assertEquals("ok", Optimistic.claimCheck(base, "D", signer, NOW + 1e12, unbounded));
        assertEquals("window", Optimistic.claimCheck(base, "D", signer, Double.NaN, def));
        assertEquals("window", Optimistic.claimCheck(base, "D", signer, Double.NaN, unbounded));
        assertEquals("window", Optimistic.claimCheck(base, "D", signer, Double.POSITIVE_INFINITY, unbounded));
        assertEquals("window", Optimistic.claimCheck(base, "D", signer, Double.NEGATIVE_INFINITY, unbounded));
        // a member the canonical form cannot write: the body is malformed (only once the signature is a string)
        Map<String, Object> odd = new LinkedHashMap<>(base);
        odd.put("note", new Object());
        assertEquals("malformed", Optimistic.claimCheck(odd, "D", signer, NOW, def));
        odd.remove("sig");
        assertEquals("signature", Optimistic.claimCheck(odd, "D", signer, NOW, def));
        assertEquals("signature", Optimistic.claimCheck(base, "D", null, NOW, def));
    }

    @Test void settlementBodyTheCanonicalFormCannotWrite() throws Exception {
        Map<String, Object> rec = m(arg0("settlementWireCheck", "open base"));
        String guardian = Keys.edFromSeed(seed(93)).id();
        assertEquals("ok", Optimistic.settlementWireCheck(rec, guardian));
        assertEquals("signature", Optimistic.settlementWireCheck(rec, null));
        Map<String, Object> odd = new LinkedHashMap<>(rec);
        odd.put("note", new Object());
        assertEquals("malformed", Optimistic.settlementWireCheck(odd, guardian));
    }

    @Test void challengeWindowEdges() {
        assertEquals(10.0, Optimistic.challengeWindowEnd(4, 6));
        assertTrue(Optimistic.withinChallengeWindow(0, 10, 10));
        assertFalse(Optimistic.withinChallengeWindow(0, 10, 10.5));
        assertTrue(Optimistic.withinChallengeWindow(0, 10, -1e300));
        assertFalse(Optimistic.withinChallengeWindow(0, 10, Double.NaN));
        assertFalse(Optimistic.withinChallengeWindow(0, 10, Double.POSITIVE_INFINITY));
        assertFalse(Optimistic.withinChallengeWindow(0, 10, Double.NEGATIVE_INFINITY));
        assertEquals("open", Optimistic.claimStatus(0, 10, 10));
        assertEquals("finalized", Optimistic.claimStatus(0, 10, Double.NEGATIVE_INFINITY));
    }

    static byte[] seed(int fill) {
        byte[] b = new byte[32];
        java.util.Arrays.fill(b, (byte) fill);
        return b;
    }
}
